WITH stimuli (news_id, news_title, is_fake, news_congruence) AS (VALUES
  (1, 'Las agencias de medicamentos son una invención del capitalismo neoliberal de la década de 1990.', false, 'true'),
  (2, 'Mario Bunge: el psicoanálisis y otras pseudociencias son perjudiciales.', false, 'true'),
  (3, 'Una pandemia de adaptación y neoliberalismo conductual en la educación.', false, 'true'),
  (4, 'Científicos explican por qué los sueños no tienen significados ocultos.', false, 'true'),
  (5, 'El pequeño Albert: un cruel experimento con un bebé de 11 meses para estudiar las fobias.', false, 'true'),
  (6, 'La comunidad reúne firmas contra las terapias psicoanalíticas públicas en casos de autismo.', false, 'true'),
  (7, 'La caja de Skinner: juegos como Candy Crush están diseñados para volverte adicto.', false, 'true'),
  (8, 'Wilhelm Reich: los controvertidos tratamientos sexuales de uno de los psicoanalistas más radicales de la historia.', false, 'true'),
  (9, 'El psiquiatra que aplicaba electroshocks a personas homosexuales.', false, 'true'),
  (10, 'La feminista que refutó a Freud y su concepto de envidia del pene.', false, 'true'),
  (11, 'Expertos piden revisar los métodos actuales de diagnóstico del trastorno bipolar.', false, 'true'),
  (12, 'La historia del sobrino argentino de Freud: es psicoanalista y cuestiona la idea de ser trans antes de la pubertad.', false, 'true'),
  (13, 'El terapeuta freudiano que hipnotizaba a sus pacientes con descargas eléctricas irá a juicio.', true, 'evidencia'),
  (14, 'Abraham Low, el pediatra y cognitivista británico que afirmaba que el autismo se curaba con terapia conductual.', true, 'psicoanalisis'),
  (15, 'Horror en Formosa: la joven hospitalizada por inanición cerró el refrigerador con un candado como parte de su terapia psicoanalítica.', true, 'evidencia'),
  (16, 'Investigan un caso de mala praxis: llevaba 5 años con depresión y su terapeuta cognitivo se negó a darle un diagnóstico.', true, 'psicoanalisis'),
  (17, 'Texas: una joven se suicida después de recibir el alta de una terapia psicoanalítica.', true, 'evidencia'),
  (18, 'Suspenden la licencia de un terapeuta cognitivo que desvestía a sus pacientes para ayudarlos a conectarse con sus cuerpos.', true, 'psicoanalisis'),
  (19, 'Un tirador en la ciudad de Dakota: «había superado todas las técnicas proyectivas; era una persona normal».', true, 'evidencia'),
  (20, 'Hallazgos recientes de neuroimagen refutan el concepto de «condicionamiento» de Watson.', true, 'psicoanalisis'),
  (21, 'El terapeuta cognitivo que entrenaba a sus pacientes con descargas eléctricas irá a juicio.', true, 'psicoanalisis'),
  (22, 'Donald Winnicott, el pediatra y psicoanalista británico que afirmaba que el autismo se curaba mediante hipnosis.', true, 'evidencia'),
  (23, 'Horror en Formosa: la joven hospitalizada por inanición cerró el refrigerador con un candado como parte de su terapia cognitiva.', true, 'psicoanalisis'),
  (24, 'Investigan un caso de mala praxis: llevaba 5 años con depresión y su terapeuta psicoanalista se negó a darle un diagnóstico.', true, 'evidencia'),
  (25, 'Texas: una joven se suicida después de recibir el alta de una terapia cognitiva breve.', true, 'psicoanalisis'),
  (26, 'Suspenden la licencia de un psicoanalista que desvestía a sus pacientes para ayudarlos a conectarse con sus cuerpos.', true, 'evidencia'),
  (27, 'Un tirador en la ciudad de Dakota: «había superado todas las técnicas psicométricas; era una persona normal».', true, 'psicoanalisis'),
  (28, 'Hallazgos recientes de neuroimagen refutan el concepto de «superyó» de Freud.', true, 'evidencia')
